var fid = Tama.Args.Get(args, "floorId", 0L);
var newE = Tama.Args.Get(args, "newE", 0.0); var newN = Tama.Args.Get(args, "newN", 0.0);
var rad = Tama.Args.Get(args, "searchRadiusM", 0.1) / 0.3048;
var floor = doc.GetElement(new ElementId((int)fid)) as Floor;
if (floor == null) throw new Exception("Floor not found.");
var tf = doc.ActiveProjectLocation.GetTotalTransform(); var inv = tf.Inverse;
var tgt2 = tf.OfPoint(new XYZ(newE/0.3048, newN/0.3048, 0));
var sketch = doc.GetElement(floor.SketchId) as Sketch;
var scope = new SketchEditScope(doc, "Adjust floor corner");
scope.Start(floor.SketchId);
var report = new List<object>();
using (var t = new Transaction(doc, "Move corner")) {
  t.Start();
  var curves = sketch.GetAllElements().Select(id => doc.GetElement(id) as CurveElement).Where(c => c != null).ToList();
  XYZ oldPt = null;
  foreach (var ce in curves) foreach (var p in new[]{ce.GeometryCurve.GetEndPoint(0), ce.GeometryCurve.GetEndPoint(1)}) { var d = new XYZ(p.X - tgt2.X, p.Y - tgt2.Y, 0).GetLength(); if (d < rad && (oldPt == null || d < new XYZ(oldPt.X - tgt2.X, oldPt.Y - tgt2.Y, 0).GetLength())) oldPt = p; }
  if (oldPt == null) throw new Exception("No sketch vertex near the target.");
  var newPt = new XYZ(tgt2.X, tgt2.Y, oldPt.Z);
  int changed = 0;
  foreach (var ce in curves) {
    var c = ce.GeometryCurve; var a = c.GetEndPoint(0); var b = c.GetEndPoint(1);
    bool aHit = a.DistanceTo(oldPt) < 1e-6, bHit = b.DistanceTo(oldPt) < 1e-6;
    if (!aHit && !bHit) continue;
    var na = aHit ? newPt : a; var nb = bHit ? newPt : b;
    Curve nc;
    if (c is Arc) {
      var mid = c.Evaluate(0.5, true);
      var chordMid = (a + b) / 2; var chordDir = (b - a).Normalize();
      var nrm = XYZ.BasisZ.CrossProduct(chordDir);
      double sag = (mid - chordMid).DotProduct(nrm);
      var nDir = (nb - na).Normalize(); var nNrm = XYZ.BasisZ.CrossProduct(nDir);
      var nMid = (na + nb) / 2 + nNrm * sag;
      nc = Arc.Create(na, nb, nMid);
      report.Add(new { edge = "arc", sagitta_mm = Math.Round(sag*304.8,1) });
    } else { nc = Line.CreateBound(na, nb); report.Add(new { edge = "line" }); }
    ce.SetGeometryCurve(nc, true); changed++;
  }
  if (changed != 2) throw new Exception("Expected 2 edges at the corner, found " + changed);
  t.Commit();
}
scope.Commit(new Tama.Failures.RollbackOnError());
var sk2 = doc.GetElement(floor.SketchId) as Sketch;
var verts = new List<object>();
foreach (CurveArray ca in sk2.Profile) foreach (Curve c in ca) { var s = inv.OfPoint(c.GetEndPoint(0)); verts.Add(new { type = c.GetType().Name, E = Math.Round(s.X*0.3048,3), N = Math.Round(s.Y*0.3048,3) }); }
return new { edges = report, sketchStartPoints = verts };
